import{_ as o,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Rook: Why Would You Ever Deploy Ceph Inside Kubernetes? - Travis Nielsen, IBM","description":"","frontmatter":{"title":"Rook: Why Would You Ever Deploy Ceph Inside Kubernetes? - Travis Nielsen, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Kubernetes","Rook","Distributed Storage","Container Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Rook_-_Why_Would_You_Ever_Deploy_Ceph_Inside_Kubernetes_-_Travis_Nielsen_IBM.md","filePath":"posts/2023/Rook_-_Why_Would_You_Ever_Deploy_Ceph_Inside_Kubernetes_-_Travis_Nielsen_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Rook_-_Why_Would_You_Ever_Deploy_Ceph_Inside_Kubernetes_-_Travis_Nielsen_IBM.md"};function t(s,e,n,_,u,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>Travis Nielsen作为Ceph项目的主要维护者和IBM存储团队的一员，在会上分享了在Kubernetes环境中部署Ceph的重要性及方法。他探讨了Ceph与Kubernetes结合的优势，并介绍了Rook在其中的管理作用。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>Kubernetes与存储的需求</strong>：</p><ul><li>Kubernetes原生并非为存储设计，但部署应用时需要存储支持。</li><li>传统上，存储通常是外部的，在私有数据中心使用云提供商存储存在限制。</li></ul></li><li><p><strong>Ceph在Kubernetes中的部署</strong>：</p><ul><li>Ceph是企业级的存储解决方案，提供对象、块和文件系统存储。</li><li>Rook作为管理层，专门用于在Kubernetes中部署和管理Ceph。</li></ul></li><li><p><strong>Rook的功能与优势</strong>：</p><ul><li>Rook使用Operator模式，通过自定义资源定义（CRDs）实现Ceph的自动化部署和管理。</li><li>Rook自2018年12月宣布稳定，已在多个生产环境中验证。</li></ul></li><li><p><strong>生产环境中的应用案例</strong>：</p><ul><li>Dimitri Mission的案例展示了Rook和Ceph在多个大学系统中的成功应用，管理着数百个节点和多PB级的数据。</li></ul></li><li><p><strong>Rook的社区与支持</strong>：</p><ul><li>Rook是CNCF毕业项目，拥有近11,000个GitHub星标和2.8亿次Docker Hub下载。</li><li>项目遵循社区优先的哲学，定期发布更新，并与Kubernetes的发布周期同步。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>Rook和Ceph的结合为Kubernetes提供了强大的存储解决方案，特别适合需要高可配置性和灵活性的企业环境。</li><li>社区将继续支持和发展Rook项目，鼓励更多用户和贡献者参与。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续推动Rook和Ceph的集成，优化在Kubernetes中的部署和管理。</li><li>加强社区建设，通过Slack、GitHub等平台收集用户反馈，持续改进项目。</li><li>在即将到来的KubeCon活动中，将会有更多关于Rook和Ceph的讨论和展示。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>Travis Nielsen将在KubeCon上有进一步的分享，并欢迎社区成员参与讨论和交流。</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>感谢Travis Nielsen的精彩分享，期待社区成员的积极参与和反馈，共同推动Rook和Ceph项目的发展。</p>',13)])])}const b=o(r,[["render",t]]);export{d as __pageData,b as default};
